public int[] countingSort(int[] arr) {
    int[] freq = new int[100];
    for (int x : arr) {
        freq[x]++;
    }
    int[] result = new int[arr.length];
    int idx = 0;
    for (int v = 0; v < 100; v++) {
        for (int c = 0; c < freq[v]; c++) {
            result[idx++] = v;
        }
    }
    return result;
}

