public int[] countingSortStable(int[] arr) {
    int n = arr.length;
    int[] count = new int[100];
    for (int x : arr) {
        count[x]++;
    }
    int[] start = new int[100];
    int running = 0;
    for (int v = 0; v < 100; v++) {
        start[v] = running;
        running += count[v];
    }
    int[] result = new int[n];
    int[] pos = start.clone();
    for (int i = 0; i < n; i++) {
        int v = arr[i];
        result[pos[v]++] = v;
    }
    return result;
}

